:12px;margin-top:4px}.profile-mini{display:flex;align-items:center;gap:10px;padding:12px}.avatar{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:#394e39;color:var(--lime);font-weight:700}.profile-mini strong{font-size:12px;display:block}.profile-mini small{font-size:10px;color:var(--muted)}.main{min-width:0}.topbar{height:67px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 35px;position:sticky;top:0;background:rgba(16,21,17,.92);backdrop-filter:blur(14px);z-index:4}.season-label{font-size:12px;color:#a6b0a7}.top-right{display:flex;align-items:center;gap:18px}.top-pill{display:flex;gap:7px;align-items:center;padding:8px 11px;border:1px solid var(--line);border-radius:8px;font-size:12px}.money{color:var(--lime);font-weight:700}.content{max-width:1450px;padding:29px 35px 48px;margin:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:24px;gap:15px}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.17em;color:var(--lime);font-weight:700;margin-bottom:8px}.page-head h1{font:600 30px var(--display);margin:0;letter-spacing:-.04em}.page-head p{margin:7px 0 0;color:var(--muted);font-size:13px}.btn{border:1px solid var(--line);background:var(--panel2);padding:10px 15px;border-radius:8px;font-size:12px;font-weight:700;transition:.15s}.btn:hover{border-color:#74805d;transform:translateY(-1px)}.btn.primary{background:var(--lime);border-color:var(--lime);color:#192018}.btn.primary:hover{background:#d6fa79}.btn.subtle{background:transparent}.btn.danger{color:var(--red)}.icon-btn{width:34px;height:34px;border:1px solid var(--line);background:var(--panel);border-radius:8px}.grid{display:grid;gap:16px}.grid.two{grid-template-columns:1.55fr 1fr}.grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;min-width:0}.card-head{display:flex;align-items:center;justify-content:space-between;padding:17px 19px;border-bottom:1px solid var(--line)}.card-head h2,.card-head h3{margin:0;font:600 14px var(--display)}.card-body{padding:18px 19px}.tag{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--line);border-radius:20px;padding:5px 8px;color:#acb7ac;font-size:10px;font-weight:700;white-space:nowrap}.tag.green{background:#26341e;color:var(--lime);border-color:#374b29}.tag.orange{color:var(--orange);background:#31261e}.tag.red{color:var(--red);background:#322322}.tag.blue{color:var(--blue);background:#202b34}.hero-card{position:relative;overflow:hidden;background:linear-gradient(115deg,#273923 0%,#1c2a20 52%,#202b21 100%);min-height:194px}.hero-card:after{content:'⚽';position:absolute;right:11%;top:14px;font-size:140px;opacity:.07;transform:rotate(-18deg)}.hero-content{position:relative;z-index:1;padding:24px}.hero-content h2{font:600 25px var(--display);margin:5px 0 3px}.hero-content p{color:#bdc9b8;margin:0 0 20px;font-size:12px}.next-match{display:flex;align-items:center;gap:16px}.team-badge{width:42px;height:42px;display:grid;place-items:center;background:#2c382d;border:1px solid #48544a;border-radius:12px;font:700 13px var(--display);color:var(--lime)}.match-center{text-align:center}.match-center .versus{font:600 15px var(--display)}.match-center small{display:block;color:#aab5aa;font-size:10px;margin-top:3px}.match-meta{display:flex;gap:8px;align-items:center}.hero-actions{display:flex;gap:9px;margin-top:20px}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:16px 0}.metric{padding:14px 15px;background:var(--panel);border:1px solid var(--line);border-radius:10px}.metric label{font-size:10px;color:var(--muted);display:block;text-transform:uppercase;letter-spacing:.08em}.metric strong{display:block;font:600 20px var(--display);margin:6px 0 2px}.metric small{font-size:10px;color:#9da99e}.standings,.data-table{width:100%;border-collapse:collapse;font-size:12px}.standings th,.data-tab