ttom:1px solid var(--line)}.player-row:last-child{border:0}.player-num{font:600 12px var(--display);color:#718074}.player-info strong{display:block;font-size:12px}.player-info small{color:var(--muted);font-size:10px}.rating{font:600 14px var(--display);color:var(--lime)}.position-pill{font-size:9px;color:#aeb9af;background:#252e27;padding:5px 7px;border-radius:5px}.table-wrap{overflow:auto}.table-wrap table{min-width:540px}.tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);padding:0 18px}.tab{background:none;border:0;color:var(--muted);padding:13px 10px 11px;font-size:11px;font-weight:700;border-bottom:2px solid transparent}.tab.active{color:var(--lime);border-color:var(--lime)}.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.select,.input{background:#111812;border:1px solid var(--line);color:var(--text);padding:10px 11px;border-radius:8px;min-width:0}.input{width:100%}.select{font-size:12px}.field{display:grid;gap:7px}.field label{color:#a7b1a7;font-size:11px;font-weight:600}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.form-grid .wide{grid-column:1/-1}.empty{padding:36px 20px;text-align:center;color:var(--muted)}.empty strong{display:block;color:var(--text);margin:8px 0}.modal-backdrop{position:fixed;inset:0;background:rgba(5,9,6,.76);backdrop-filter:blur(6px);display:grid;place-items:center;padding:15px;z-index:20}.modal{width:min(600px,100%);max-height:min(90vh,850px);overflow:auto;background:#18211a;border:1px solid #344237;border-radius:15px;box-shadow:0 24px 90px #0009}.modal.wide-modal{width:min(760px,100%)}.modal-head{padding:20px 22px 15px;border-bottom:1px solid var(--line);display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.modal-head h2{font:600 20px var(--display);margin:0}.modal-head p{color:var(--muted);font-size:11px;margin:6px 0 0}.modal-body{padding:20px 22px}.modal-foot{display:flex;justify-content:flex-end;gap:9px;padding:14px 22px;border-top:1px solid var(--line)}.toast{position:fixed;bottom:22px;left:50%;transform:translate(-50%,20px);background:#d5f87d;color:#172016;border-radius:8px;padding:11px 17px;font-size:12px;font-weight:700;opacity:0;pointer-events:none;transition:.22s;z-index:40;box-shadow:0 8px 25px #0005}.toast.show{opacity:1;transform:translate(-50%,0)}.match-layout{display:grid;grid-template-columns:1fr 250px;gap:16px}.pitch{background:linear-gradient(90deg,rgba(255,255,255,.025) 50%,transparent 50%),#263c2d;background-size:70px 100%;border:1px solid #49634a;border-radius:11px;padding:21px;position:relative;min-height:365px}.pitch:before{content:'';position:absolute;inset:12px;border:1px solid #66816a55;border-radius:6px;pointer-events:none}.pitch-line{position:absolute;left:50%;top:12px;bottom:12px;border-left:1px solid #66816a55}.pitch-circle{position:absolute;left:50%;top:50%;width:82px;height:82px;border:1px solid #66816a55;border-radius:50%;transform:translate(-50%,-50%)}.formation{position:relative;z-index:1;display:grid;grid-template-columns:repeat(4,1fr);gap:21px 9px;min-height:320px;align-items:center}.player-token{text-align:center;cursor:pointer}.player-token .shirt{width:34px;height:32px;margin:auto auto 4px;background:var(--lime);clip-path:polygon(25% 0,40% 10%,60% 10%,75% 0,100% 20%,87% 38%,78% 30%,78% 100%,22% 100%,22% 30%,13% 38%,0 20%);display:grid;place-items:center;color:#1b2419;font-size:10px;font-weight:700;padding-top:5px}.player-token small{font-size:9px;text-shadow:0 1px 3px #000;color:white;display:block;white-space:nowrap}.bench-list{display:grid;gap:8px}.bench-player{display:flex;justify-content:space-between;align-items:center;font-size:11px;padding:8px;border:1px solid var(--line);border-radius:7px}.bench-player button{font-size:10px;padding:5px 8px}.live-score{text-align:center;padding:22px 10px;background:#18221a;border:1px solid var(--line);border-radius:11px}.live-score .teams{display:flex;justify-content:center;align-items:center;gap:20px}.live-score .score{font:700 31px var(--display);color:var(--lime)}.live-clock{font:600 18px var(--display);color:var(--orange);margin-top:10px}.commentary{height:137px;overflow:auto;display:flex;flex-direction:column-reverse;gap:7px;padding:11px;background:#111812;border:1px solid var(--line);border-radius:8px}.commentary div{font-size:10px;color:#aab5ab}.commentary b{color:var(--text)}.event{display:flex;align-items:center;justify-content:space-between;font-size:11px;padding:9px 0;border-bottom:1px solid var(--line)}.event:last-child{border:0}.trophy{font-size:29px}.home-screen{min-height:100vh;background:radial-gradient(ellipse at 68% 28%,#273a27 0,transparent 37%),#101511;display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:9vw;align-items:center;padding:7vw 11vw}.home-logo{font:700 clamp(38px,7vw,72px)/.95 var(--display);letter-spacing:-.07em}.home-logo span{color:var(--lime)}.home-copy{font-size:14px;color:#a2afa3;max-width:490px;line-height:1.7;margin:17px 0 32px}.home-foot{font-size:10px;color:#667268;margin-top:58px}.menu-panel{padding:20px;border:1px solid #2a362c;background:#171f19de;border-radius:14px;box-shadow:0 22px 100px #0005}.menu-panel h2{font:600 19px var(--display);margin:7px 6px 15px}.menu-buttons{display:grid;gap:7px}.menu-buttons button{padding:13px;background:transparent;border:1px solid transparent;border-radius:8px;text-align:left;font:700 11px var(--display);letter-spacing:.08em;color:#c6d0c4}.menu-buttons button:hover{background:#243126;border-color:#374938;color:var(--lime)}.menu-buttons button.primary-menu{background:var(--lime);color:#182018}.menu-buttons button.primary-menu:hover{background:#d9fa82}.slots{display:grid;gap:8px}.slot{display:flex;justify-content:space-between;align-items:center;padding:12px;border:1px solid var(--line);border-radius:8px}.slot strong{font-size:12px}.slot small{display:block;color:var(--muted);font-size:10px;margin-top:4px}.mobile-menu{display:none}.notice{padding:12px 14px;border:1px solid #3c493d;background:#20291f;border-radius:8px;color:#bdc8bc;font-size:11px;line-height:1.55}.rating-bar{display:flex;align-items:center;gap:9px}.rating-bar .progress{width:80px}.status-good{color:var(--lime)}.status-bad{color:var(--red)}.competition-header{display:flex;align-items:center;gap:13px;padding:18px 0}.competition-emblem{width:48px;height:48px;display:grid;place-items:center;border-radius:13px;background:#283526;font-size:20px;color:var(--lime)}.competition-header h2{font:600 18px var(--display);margin:0}.competition-header small{color:var(--muted)}.badge-wrap{display:flex;flex-wrap:wrap;gap:7px}.divider{height:1px;background:var(--line);margin:14px 0}.mobile-bottom{display:none}
