@media(max-width:720px){body{font-size:13px}.app-shell{display:block;padding-bottom:62px}.sidebar{display:none}.topbar{height:56px;padding:0 15px}.topbar .season-label{font-size:10px}.top-right{gap:7px}.top-pill{padding:7px 8px;font-size:10px}.content{padding:22px 14px 30px}.page-head{margin-bottom:18px}.page-head h1{font-size:25px}.page-head p{font-size:11px}.grid.two,.grid.three{grid-template-columns:1fr}.metric-grid{grid-template-columns:repeat(2,1fr);gap:8px;margin:11px 0}.metric{padding:12px}.metric strong{font-size:18px}.hero-card{min-height:0}.hero-content{padding:19px}.hero-content h2{font-size:21px}.hero-card:after{right:4%;font-size:100px}.card-head{padding:14px}.card-body{padding:14px}.standings td,.data-table td{padding:8px 6px}.standings th,.data-table th{padding:8px 6px}.match-layout{grid-template-columns:1fr}.pitch{min-height:300px;padding:15px}.formation{min-height:265px;gap:14px 4px}.player-token .shirt{width:29px;height:27px}.player-token small{font-size:8px}.home-screen{min-height:100vh;grid-template-columns:1fr;padding:12vh 7vw 7vh;gap:32px;align-content:center}.home-copy{margin:14px 0 20px}.home-foot{margin-top:24px}.menu-panel{max-width:480px}.mobile-bottom{display:grid;position:fixed;bottom:0;left:0;right:0;height:60px;background:#121914;border-top:1px solid var(--line);grid-template-columns:repeat(5,1fr);z-index:8;padding-bottom:env(safe-area-inset-bottom)}.mobile-bottom button{border:0;background:none;color:#849087;font-size:9px;display:grid;place-items:center;gap:2px}.mobile-bottom button span{font-size:17px}.mobile-bottom button.active{color:var(--lime)}.form-grid{gap:11px}.form-grid .wide{grid-column:1/-1}.modal-body{padding:16px}.modal-head{padding:17px 16px}.modal-foot{padding:13px 16px}.toolbar{width:100%}.toolbar .select{flex:1}.table-wrap table{min-width:510px}.form-dots{gap:2px}.form-dot{height:16px;width:16px}.page-head>.btn{padding:9px 10px;font-size:10px}.match-layout .grid.two{grid-template-columns:1fr}}

const STORE_KEY='topo-career-v1';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
let slots=loadSlots(), currentSlot=null, page='home', modal=null, toastTimer;
function loadSlots(){try{return JSON.parse(localStorage.getItem(STORE_KEY)||'{}')}catch{return {}}}
function persist(){localStorage.setItem(STORE_KEY,JSON.stringify(slots))}
function active(){return currentSlot?slots[currentSlot]:null}
function uid(prefix='id'){return prefix+'-'+Math.random().toString(36).slice(2,9)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(n){let a=Math.abs(n);return a>=1e9?'€'+(n/1e9).toFixed(1)+' bi':a>=1e6?'€'+(n/1e6).toFixed(1)+' mi':a>=1e3?'€'+Math.round(n/1e3)+' mil':'€'+Math.round(n)}
function initials(s){return s.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function clubBy(id){return CLUBS.find(c=>c.id===id)||CLUBS[0]}
function getLeagueClubs(country,division){return CLUBS.filter(c=>c.country===country&&c.division===division)}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function escAttr(s){return esc(s)}
function genSquad(club,seed=1){let rand=seeded(seed+club.reputation*81);return Array.from({length:22},(_,i)=>{let pos=POSITIONS[i],base=club.reputation-(club.division.includes('B')||club.division.includes('2')?8:0),rating=clamp(Math.round(base-18+rand()*25),47,91);return{id:uid('p'),name:`${FIRST_NAMES[Math.floor(rand()*FIRST_NAMES.length)]} ${LAST_NAMES[Math.floor(rand()*LAST_NAMES.length)]}`,age:18+Math.floor(rand()*17),pos,rating,potential:clamp(rating+Math.floor(rand()*20),rating,94),fitness:85+Math.floor(rand()*16),morale:65+Math.floor(rand()*31),value:(rating*rating*1900)+Math.floor(rand()*800000),wage:Math.round(rating*850),goals:0,assists:0,apps:0,injury:0,nation:club.country==='Brasil'?'BRA':club.country==='Portugal'?'POR':club.country==='Argentina'?'ARG':'INT'};})}
function seeded(seed){let x=Math.sin(seed*999.17)*10000;return()=>{x=Math.sin(x+seed+78.233)*43758.5453;return x-Math.floor(x)}}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function clubStrength(club){return club.reputation}
function createCareer(form){let c=clubBy(form.club), leagueClubs=getLeagueClubs(c.country,c.division);let teams=leagueClubs.map((club,i)=>({clubId:club.id,squad:genSquad(club,31+i*113),points:0,w:0,d:0,l:0,gf:0,ga:0}));let you=teams.find(t=>t.clubId===c.id);let fixtures=makeFixtures(leagueClubs);let id='save-'+Date.now().toString(36);let career={id,saveName:form.saveName||`${form.coach} — ${c.name}`,coach:{name:form.coach,nation:form.nation,age:+form.age,look:form.look,experience:form.experience,reputation:form.experience==='Elite'?62:form.experience==='Pro'?42:25,licenses:form.experience==='Elite'?['Pro continental','A','B']:form.experience==='Pro'?['A','B']:['B'],popularity:40,history:[{club:c.id,joined:'Julho 2025',left:null}],titles:0,w:0,d:0,l:0,marketValue:50000,salary:25000},clubId:c.id,country:c.country,division:c.division,season:2025,date:'2025-07-14',round:0,fixtures,teams,formation:'4-3-3',tactic:'Equilibrado',lineup:you.squad.slice(0,11).map(p=>p.id),captain:you.squad[6].id,training:'Equilibrado',difficulty:form.difficulty,realism:form.realism,matchLength:form.matchLength,budget:c.budget,salaries:you.squad.reduce((s,p)=>s+p.wage,0),contract:2,boardTrust:68,fanMood:65,news:[],offers:[],messages:[],history:[],transferList:[],events:[],seasonStats:{played:0,w:0,d:0,l:0,scored:0,conceded:0},trophies:[],settings:{sound:true,notifications:true},created:new Date().toISOString(),lastResult:null,editorNotes:[]};career.messages.push(makeMessage('board','Bem-vindo ao clube',`A diretoria espera que você conduza o ${c.name} a uma temporada competitiva. O objetivo é terminar entre os 4 primeiros. Boa sorte, mister!`));career.messages.push(makeMessage('press','Sua primeira coletiva',`A imprensa quer conhecer o novo treinador. Qual será o seu tom nesta temporada?`));slots[id]=career;currentSlot=id;persist();page='dashboard';render()}
function makeFixtures(clubs){let list=clubs.map(c=>c.id);if(list.length%2)list.push(null);let n=list.length,rounds=[];for(let r=0;r<n-1;r++){let games=[];for(let i=0;i<n/2;i++){let a=list[i],b=list[n-1-i];if(a&&b)games.push({home:r%2?b:a,away:r%2?a:b,result:null});}rounds.push(games);list=[list[0],list[n-1],...list.slice(1,n-1)];}return [...rounds,...rounds.map(x=>x.map(m=>({home:m.away,away:m.home,result:null})))].map((games,i)=>({date:dateForRound(i),games}));}
function dateForRound(i){let d=new Date(Date.UTC(2025,7,9+i*7));return d.toISOString().slice(0,10)}
function makeMessage(type,title,body){return{id:uid('msg'),type,title,body,date:active()?.date||'2025-07-14',read:false,actions:[]}}
