argin-bottom:12px">${esc(msg.body.slice(0,116))}${msg.body.length>116?'…':''}</p><button class="btn" data-page="inbox">ABRIR CAIXA DE ENTRADA →</button>`:`<div class="row"><div><strong style="font-size:12px">Treino da equipe</strong><div class="muted" style="font-size:10px;margin-top:4px">${esc(a.training)} · ${team.squad.length} jogadores disponíveis</div></div><span class="tag green">● ATIVO</span></div>`}</div></div></div></div>`}
function calendarPreview(){let a=active(),arr=[];for(let r=a.round;r<Math.min(a.round+3,a.fixtures.length);r++){let game=a.fixtures[r].games.find(g=>g.home===a.clubId||g.away===a.clubId);if(!game)continue;let home=clubBy(game.home),away=clubBy(game.away),res=game.result;arr.push(`<div class="calendar-row"><span class="cal-date">${formatDate(a.fixtures[r].date)}</span><div class="cal-match"><span class="mini-badge" style="color:${home.colors}">${home.short.slice(0,3)}</span><strong>${game.home===a.clubId?'Você':'Fora'} × ${esc(game.away===a.clubId?home.name:away.name)}</strong></div><span class="cal-result">${res?`${res.home} – ${res.away}`:'—'}</span></div>`)}return arr.join('')||'<div class="empty">Temporada encerrada.</div>'}
function squadPage(){let a=active(),team=currentTeam(),filter=a.squadFilter||'Todos';let players=[...team.squad].sort((x,y)=>y.rating-x.rating).filter(p=>filter==='Todos'||p.pos===filter);return `${head('ELENCO PRINCIPAL','O grupo de trabalho',`${team.squad.length} atletas · Folha salarial ${money(a.salaries)} / mês`,'<button class="btn primary" data-page="tactics">⌘ &nbsp; ESCALAÇÃO</button>')}<div class="grid two"><div class="card"><div class="card-head"><h2>Jogadores</h2><div class="toolbar"><select class="select" data-change="squad-filter"><option>Todos</option>${['GOL','ZAG','LD','LE','VOL','MC','MEI','PD','PE','ATA'].map(p=>`<option ${filter===p?'selected':''}>${p}</option>`).join('')}</select><span class="tag">${players.length} atletas</span></div></div><div class="card-body" style="padding-top:7px">${players.map((p,i)=>playerRow(p,i)).join('')}</div></div><div class="stack"><div class="card"><div class="card-head"><h2>Resumo do elenco</h2></div><div class="card-body stack"><div class="row"><span class="muted">Média de idade</span><strong>${(team.squad.reduce((s,p)=>s+p.age,0)/team.squad.length).toFixed(1)} anos</strong></div><div class="row"><span class="muted">Força média</span><strong>${Math.round(team.squad.reduce((s,p)=>s+p.rating,0)/team.squad.length)} OVR</strong></div><div class="row"><span class="muted">Valor do elenco</span><strong>${money(team.squad.reduce((s,p)=>s+p.value,0))}</strong></div><div class="row"><span class="muted">Jogadores lesionados</span><strong>${team.squad.filter(p=>p.injury>0).length}</strong></div><div class="divider"></div><button class="btn" data-page="transfers">ABRIR MERCADO →</button></div></div><div class="card"><div class="card-head"><h2>Treino da semana</h2><span class="tag green">DESENVOLVIMENTO</span></div><div class="card-body"><p class="muted" style="font-size:11px;line-height:1.6;margin:0 0 12px">O foco de treino influencia o crescimento dos atletas e a preparação para a próxima partida.</p><select class="select" style="width:100%" data-change="training">${['Equilibrado','Ataque','Defesa','Preparação física','Desenvolvimento jovem'].map(x=>`<option ${a.training===x?'selected':''}>${x}</option>`).join('')}</select></div></div></div></div>`}
function playerRow(p,i){return `<div class="player-row"><div class="player-num">${String(i+1).padStart(2,'0')}</div><div class="player-info"><strong>${esc(p.name)} ${p.injury?'<span class="tag red">LESÃO</span>':''}</strong><small>${p.age} anos · ${p.nation} · ${money(p.value)}</small></div><span class="position-pill">${p.pos}</span><div class="rating">${p.rating}</div></div>`}

