function tacticsPage(){let a=active(),team=currentTeam(),line=FORMATIONS[a.formation]||FORMATIONS['4-3-3'];let xi=line.map((pos,i)=>team.squad.find(p=>p.id===a.lineup[i])||team.squad[i]);return `${head('PLANO DE JOGO','Tática e escalação','Monte seu time titular e defina como a equipe joga.','<button class="btn primary" data-action="save-tactics">SALVAR ALTERAÇÕES</button>')}<div class="match-layout"><div class="card"><div class="card-head"><h2>Quadro tático</h2><div class="toolbar"><select class="select" data-change="formation">${Object.keys(FORMATIONS).map(f=>`<option ${a.formation===f?'selected':''}>${f}</option>`).join('')}</select><select class="select" data-change="tactic">${['Equilibrado','Pressão alta','Contra-ataque','Posse de bola','Defensivo'].map(x=>`<option ${a.tactic===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="card-body"><div class="pitch"><div class="pitch-line"></div><div class="pitch-circle"></div><div class="formation">${xi.map((p,i)=>`<div class="player-token" data-action="choose-player" data-index="${i}"><div class="shirt">${p.rating}</div><small>${esc(p.name.split(' ').slice(-1)[0])}</small></div>`).join('')}</div></div><p class="muted" style="font-size:10px;margin:12px 0 0">Toque em um atleta para trocar o titular. Os 11 primeiros da lista são o banco.</p></div></div><div class="stack"><div class="card"><div class="card-head"><h2>Banco de reservas</h2><span class="tag">7 DISPONÍVEIS</span></div><div class="card-body"><div class="bench-list">${team.squad.filter(p=>!a.lineup.includes(p.id)).slice(0,7).map(p=>`<div class="bench-player"><span><b>${esc(p.name)}</b><span class="muted"> · ${p.pos}</span></span><span class="rating">${p.rating}</span></div>`).join('')}</div></div></div><div class="card"><div class="card-head"><h2>Leitura do time</h2></div><div class="card-body stack"><div class="row"><span class="muted">Força titular</span><strong>${Math.round(xi.reduce((s,p)=>s+p.rating,0)/xi.length)} OVR</strong></div><div class="row"><span class="muted">Forma física média</span><strong>${Math.round(xi.reduce((s,p)=>s+p.fitness,0)/xi.length)}%</strong></div><div class="row"><span class="muted">Entrosamento</span><strong>${Math.min(96,68+Math.round(a.round*1.4))}%</strong></div><div class="divider"></div><span class="tag green">● ${esc(a.tactic.toUpperCase())}</span></div></div></div></div>`}
function tablePage(){let a=active(),country=a.country;return `${head('COMPETIÇÕES','A corrida pelo título',`${a.division} · ${a.country} · Temporada ${a.season}/${a.season+1}`,'<button class="btn" data-page="calendar">▣ &nbsp; VER CALENDÁRIO</button>')}<div class="card"><div class="tabs"><button class="tab active">CLASSIFICAÇÃO</button><button class="tab" data-page="calendar">CALENDÁRIO</button><button class="tab" data-action="competition-info">REGRAS</button></div><div class="card-body"><div class="competition-header"><div class="competition-emblem">♛</div><div><h2>${esc(a.division)}</h2><small>${esc(a.country)} · ${a.teams.length} clubes · ${a.fixtures.length} rodadas</small></div><span class="tag green" style="margin-left:auto">${a.round>=a.fixtures.length?'FINALIZADA':`RODADA ${a.round+1} / ${a.fixtures.length}`}</span></div>${standingsTable()}<div class="notice" style="margin-top:16px">Formato: pontos corridos, vitória vale 3 pontos e empate vale 1. O calendário é gerado em turno e returno. Promoção e rebaixamento dependem da estrutura da divisão e serão aplicados nas temporadas seguintes.</div></div></div><div class="section-gap"><div class="page-head"><div><div class="eyebrow">MAPA GLOBAL</div><h1 style="font-size:21px">Competições disponíveis</h1><p>Base internacional expansível com ligas cadastradas por país.</p></div><select class="select" data-change="country-filter">${COMPETITIONS.map(c=>`<option ${country===c.country?'selected':''}>${c.country}</option>`).join('')}</select></div><div class="card"><div class="card-body"><div class="badge-wrap">${(COMPETITIONS.find(c=>c.country===country)?.leagues||[]).map(l=>`<span class="tag">${esc(l)}</span>`).join('')}</div><div class="notice" style="margin-top:14px">Esta carreira está vinculada a ${esc(a.country)} · ${esc(a.division)}. O catálogo contém ${COMPETITIONS.length} países e divisões configuráveis; a simulação de temporada utiliza elencos ativos licenciados por dados desta edição.</div></div></div></div>`}
function calendarPage(){let a=active();return `${head('TEMPORADA '+a.season,'Calendário de jogos','Turno e returno · ${a.fixtures.length} rodadas no campeonato','<button class="btn primary" data-action="simulate-match">SIMULAR PRÓXIMO JOGO →</button>')}<div class="card"><div class="card-head"><h2>Todos os jogos · ${esc(a.division)}</h2><span class="tag">${a.round} / ${a.fixtures.length} RODADAS CONCLUÍDAS</span></div><div class="card-body">${a.fixtures.map((round,i)=>{let g=round.games.find(x=>x.home===a.clubId||x.away===a.clubId),h=clubBy(g.home),v=clubBy(g.away);return `<div class="calendar-row"><span class="cal-date">${formatDate(round.date)}</span><div class="cal-match"><span class="mini-badge" style="color:${h.colors}">${h.short}</span><strong>${esc(h.name)} ${g.result?`${g.result.home} – ${g.result.away}`:'vs'} ${esc(v.name)}</strong><span class="mini-badge" style="color:${v.colors}">${v.short}</span></div><span class="tag ${g.result?'':'blue'}">${g.result?(g.result.outcome[a.clubId]==='W'?'VITÓRIA':g.result.outcome[a.clubId]==='D'?'EMPATE':'DERROTA'):i===a.round?'PRÓXIMO':'AGENDADO'}</span></div>`}).join('')}</div></div>`}
function marketPagePlayers(){let a=active();if(!a.market){let candidates=[];for(let t of a.teams)if(t.clubId!==a.clubId)for(let p of t.squad)candidates.push({...p,from:t.clubId,fee:Math.round(p.value*(.75+Math.random()*.55))});let rand=seeded(a.season*13+a.round*9+a.coach.reputation);for(let i=0;i<18;i++){let p=genSquad(clubBy(a.clubId),1000+i)[Math.floor(rand()*22)];candidates.push({...p,id:uid('market'),from:'free',fee:Math.round(p.value*.3),wage:Math.round(p.wage*.8)})}a.market=candidates.sort((x,y)=>y.rating-x.rating)}return a.market}
function transfersPage(){let a=active(),team=currentTeam(),list=marketPagePlayers().filter(p=>!a.marketSearch||p.name.toLowerCase().includes(a.marketSearch.toLowerCase())).filter(p=>a.marketPos==='Todos'||p.pos===a.marketPos).slice(0,32);return `${head('MERCADO DE TRANSFERÊNCIAS','Construa seu elenco',`Orçamento disponível ${money(a.budget)} · Folha mensal ${money(a.salaries)}`)}<div class="grid two"><div class="card"><div class="card-head"><h2>Observação de jogadores</h2><div class="toolbar"><input class="input" style="width:140px;padding:8px" placeholder="Buscar jogador…" value="${escAttr(a.marketSearch||'')}" data-input="market-search"><select class="select" data-change="market-pos"><option>Todos</option>${['GOL','ZAG','LD','LE','VOL','MC','MEI','PD','PE','ATA'].map(p=>`<option ${a.marketPos===p?'selected':''}>${p}</option>`).join('')}</select></div></div><div class="card-body" style="padding-top:6px">${list.map(p=>`<div class="player-row" style="grid-template-columns:1fr auto auto"><div class="player-info"><strong>${esc(p.name)}</strong><small>${p.age} anos · ${p.pos} · ${p.from==='free'?'Livre':esc(clubBy(p.from).name)}</small></div><div class="player-info" style="text-align:right"><strong>${money(p.fee)}</strong><small>salário ${money(p.wage)}/mês</small></div><button class="btn ${p.from==='free'?'':'primary'}" style="padding:7px 9px;font-size:10px" data-action="sign-player" data-id="${p.id}">${p.from==='free'?'CONTRATAR':'NEGOCIAR'}</button></div>`).join('')||'<div class="empty">Nenhum jogador encontrado.</div>'}</div></div><div class="stack"><div class="card"><div class="card-head"><h2>Finanças do clube</h2></div><div class="card-body stack"><div class="row"><span class="muted">Orçamento de transferências</span><strong class="money">${money(a.budget)}</strong></div><div class="row"><span class="muted">Folha salarial atual</span><strong>${money(a.salaries)} / mês</strong></div><div class="row"><span class="muted">Limite estimado</span><strong>${money(a.budget*.12)} / mês</strong></div><div class="progress"><span style="width:${clamp(a.salaries/(a.budget*.12)*100,4,100)}%"></span></div><div class="notice">Negocie com responsabilidade: custo de transferência sai do orçamento e o salário é adicionado à folha.</div></div></div><div class="card"><div class="card-head"><h2>Coloque à venda</h2></div><div class="card-body"><select class="select" style="width:100%" id="sell-player">${team.squad.map(p=>`<option value="${p.id}">${esc(p.name)} · ${money(p.value)}</option>`).join('')}</select><button class="btn" style="width:100%;margin-top:9px" data-action="sell-player">RECEBER PROPOSTA</button></div></div></div></div>`}

