ade</span><strong>${a.coach.popularity} / 100</strong></div><div class="row"><span class="muted">Licenças</span><strong>${a.coach.licenses.join(' · ')}</strong></div><div class="row"><span class="muted">Salário mensal</span><strong>${money(a.coach.salary)}</strong></div><div class="row"><span class="muted">Valor de mercado</span><strong>${money(a.coach.marketValue)}</strong></div></div></div><div class="card"><div class="card-head"><h2>Histórico de carreira</h2></div><div class="card-body">${a.coach.history.map(h=>`<div class="event"><span><b>${esc(clubBy(h.club).name)}</b><small class="muted" style="display:block;margin-top:3px">${h.joined}${h.left?' — '+h.left:' · Atual'}</small></span><span class="tag">${a.coach.titles} TÍTULOS</span></div>`).join('')}<div class="event"><span><b>Campanha atual</b></span><span>${a.coach.w}V · ${a.coach.d}E · ${a.coach.l}D</span></div></div></div></div></div>`}

